import React from 'react';
import { motion, useReducedMotion } from 'framer-motion';
import AppButton from '../../../components/ui/AppButton';
import TeamNameWithFlag from './TeamNameWithFlag';
import PlayerNameWithType from './PlayerNameWithType';
import ScoreboardModal from './ScoreboardModal';

export function TossResultCard({
  winner,
  decision,
  commentator,
  isUserWinner,
  onUserDecision,
}) {
  const isBat = decision === 'bat';
  const remainingForUser = isBat ? 'bowl' : 'bat';

  return (
    <div className="sim-result-block">
      <h3 className="sim-result-title">
        <span className="sim-card-kicker">Toss Winner</span>
        <TeamNameWithFlag teamName={winner} /> won the toss
      </h3>
      <p className="sim-result-lede">Commentator: {commentator}</p>

      {isUserWinner ? (
        <>
          <p className="sim-result-lede">You won the toss. Choose what your team does first.</p>
          <div className="sim-choice-icons sim-choice-buttons">
            <button onClick={() => onUserDecision('bat')} className={isBat ? 'active' : 'faded'}>
              <img src="/asset/img/icon/cricket-bat.png" alt="bat" />
            </button>
            <button onClick={() => onUserDecision('bowl')} className={isBat ? 'faded' : 'active'}>
              <img src="/asset/img/icon/cricket-ball.png" alt="ball" />
            </button>
          </div>
        </>
      ) : (
        <>
          <p className="sim-result-lede">Waiting for opponent decision...</p>
          <div className="sim-choice-icons sim-choice-buttons">
            <button
              disabled={isBat}
              onClick={() => onUserDecision('bat')}
              className={isBat ? 'active locked' : 'faded selectable'}
            >
              <img src="/asset/img/icon/cricket-bat.png" alt="bat" />
            </button>
            <button
              disabled={!isBat}
              onClick={() => onUserDecision('bowl')}
              className={isBat ? 'faded selectable' : 'active locked'}
            >
              <img src="/asset/img/icon/cricket-ball.png" alt="ball" />
            </button>
          </div>
          <p className="sim-result-lede">Opponent chose to {decision} first. Click your only available option to continue: {remainingForUser}.</p>
        </>
      )}
    </div>
  );
}

export function MatchResultCard({
  teamOneLine,
  teamTwoLine,
  teamOneName,
  teamTwoName,
  teamOneScore,
  teamOneWickets,
  teamTwoScore,
  teamTwoWickets,
  teamOneOvers,
  teamTwoOvers,
  summary,
  momRecommendations,
  onSelectManOfTheMatch,
  onPrimaryAction,
  primaryActionLabel = 'Play New Match',
  showScoreboard,
  scorecard,
  onCloseScoreboard,
  scoreboardInParentDialog = false,
  autoSelectTopMomOnPrimaryAction = false,
}) {
  const prefersReducedMotion = useReducedMotion();
  const [isMomPanelHidden, setIsMomPanelHidden] = React.useState(false);

  React.useEffect(() => {
    setIsMomPanelHidden(false);
  }, [summary, teamOneLine, teamTwoLine]);

  const handleSelectMom = (player) => {
    if (!player) {
      return;
    }

    onSelectManOfTheMatch?.(player);
    setIsMomPanelHidden(true);
  };

  const handlePrimaryActionClick = () => {
    if (autoSelectTopMomOnPrimaryAction && !isMomPanelHidden && Array.isArray(momRecommendations) && momRecommendations.length > 0) {
      handleSelectMom(momRecommendations[0]);
    }

    onPrimaryAction?.();
  };

  const renderInningsScoreboard = (inningsData, keyPrefix) => {
    if (!inningsData) {
      return null;
    }

    return (
      <div className="sim-scoreboard-block">
        <p className="sim-section-title">{inningsData.title}</p>
        <p>{inningsData.line} ({inningsData.overs})</p>

        <div className="sim-scoreboard-table-wrap">
          <p className="sim-section-title">Batting</p>
          <table className="sim-scoreboard-table">
            <thead>
              <tr>
                <th>Batsman</th>
                <th>Runs</th>
                <th>Balls</th>
                <th>SR</th>
                <th>Dismissal</th>
              </tr>
            </thead>
            <tbody>
              {inningsData.battingRows.map((row) => (
                <tr key={`${keyPrefix}-bat-${row.name}`} className={row.isNotOut ? 'sim-scoreboard-row-notout' : ''}>
                  <td><PlayerNameWithType player={row} /></td>
                  <td>{row.runs}</td>
                  <td>{row.balls}</td>
                  <td>{row.strikeRate}</td>
                  <td>{row.dismissal}</td>
                </tr>
              ))}
            </tbody>
          </table>

          <p className="sim-section-title">Bowling</p>
          <table className="sim-scoreboard-table">
            <thead>
              <tr>
                <th>Bowler</th>
                <th>Overs</th>
                <th>Runs</th>
                <th>Economy</th>
                <th>Avg/Wk</th>
                <th>Wkts</th>
              </tr>
            </thead>
            <tbody>
              {inningsData.bowlingRows.map((row) => (
                <tr key={`${keyPrefix}-bowl-${row.name}`} className={row.isCurrent ? 'sim-scoreboard-row-current' : ''}>
                  <td><PlayerNameWithType player={row} /></td>
                  <td>{row.overs}</td>
                  <td>{row.runsConceded}</td>
                  <td>{row.economy}</td>
                  <td>{row.avgPerWicket}</td>
                  <td>{row.wickets}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    );
  };

  const scoreboardTables = (
    <>
      {renderInningsScoreboard(scorecard?.currentInnings, 'current')}
      {scorecard?.previousInnings ? renderInningsScoreboard(scorecard.previousInnings, 'previous') : null}
    </>
  );

  return (
    <div className="sim-final-grid">
      <div className="sim-final-card">
        <span className="sim-card-kicker">First Innings</span>
        <h4>
          {teamOneName ? <TeamNameWithFlag teamName={teamOneName} /> : null}{' '}
          {Number.isFinite(teamOneScore) && Number.isFinite(teamOneWickets)
            ? `${teamOneScore}/${teamOneWickets}`
            : teamOneLine}
        </h4>
        <p>Overs: {teamOneOvers}</p>
      </div>
      <div className="sim-final-card">
        <span className="sim-card-kicker">Second Innings</span>
        <h4>
          {teamTwoName ? <TeamNameWithFlag teamName={teamTwoName} /> : null}{' '}
          {Number.isFinite(teamTwoScore) && Number.isFinite(teamTwoWickets)
            ? `${teamTwoScore}/${teamTwoWickets}`
            : teamTwoLine}
        </h4>
        <p>Overs: {teamTwoOvers}</p>
      </div>
      <motion.h3
        className="sim-winner-line"
        animate={prefersReducedMotion ? { scale: 1 } : { scale: [1, 1.03, 1] }}
        transition={{ duration: prefersReducedMotion ? 0 : 1.2, repeat: prefersReducedMotion ? 0 : Infinity }}
      >
        {summary}
      </motion.h3>
      {!isMomPanelHidden && Array.isArray(momRecommendations) && momRecommendations.length ? (
        <div className="sim-mom-panel">
          <h4>Man of the Match Suggestions</h4>
          <p>Choose one player from the top 5 ranked list.</p>
          <ol className="sim-mom-list sim-mom-list-plain">
            {momRecommendations.map((player) => (
              <li key={`${player.rank}-${player.team}-${player.name}`} className={player.recommended ? 'sim-mom-item-recommended' : ''}>
                <div className="sim-mom-head">
                  <strong>#{player.rank} <PlayerNameWithType player={player} /></strong>
                  {player.recommended ? <span className="sim-mom-badge">Recommended</span> : null}
                  <button
                    type="button"
                    className="sim-mom-select-btn"
                    onClick={() => handleSelectMom(player)}
                    aria-label={`Select ${player.name} as Man of the Match`}
                    title="Select as Man of the Match"
                  >
                    <svg viewBox="0 0 24 24" aria-hidden="true">
                      <path d="m5 12.5 4.5 4.5L19 7" />
                    </svg>
                  </button>
                </div>
                <div className="sim-mom-lines">
                  <p>Batting Performance {player.runs}({player.balls}) [{player.strikeRate}] {player.notOut ? 'Not Out' : ''}</p>
                  <p>Bowling Performance {player.oversBowled}-{player.runsConceded}-{player.wickets}</p>
                  <p>Team: {player.team} | Total MOM Points: {player.points}</p>
                  {Array.isArray(player.notes) && player.notes.length ? (
                    <ul className="sim-mom-points-list">
                      {player.notes.map((note) => (
                        <li key={`${player.name}-${note}`}>MOM Point: {note}</li>
                      ))}
                    </ul>
                  ) : null}
                </div>
              </li>
            ))}
          </ol>
        </div>
      ) : null}
      {showScoreboard && scoreboardInParentDialog ? (
        <div className="sim-scoreboard-panel">
          <h4>Full Scoreboard</h4>
          {scoreboardTables}
        </div>
      ) : null}
      {showScoreboard && !scoreboardInParentDialog ? (
        <ScoreboardModal onClose={onCloseScoreboard}>{scoreboardTables}</ScoreboardModal>
      ) : null}
      <AppButton text={primaryActionLabel} onClick={handlePrimaryActionClick} />
    </div>
  );
}
